# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def make(last, first):
    return Student("id", last, first, "A")


class SeatRowTests(unittest.TestCase):
    def test_sorted_and_split_into_rows(self):
        people = [
            make("Halloway", "Juno"),
            make("Dunmere", "Piet"),
            make("Quill", "Anna")
        ]
        self.assertEqual(
            seat_rows(people, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Quill, Anna"
            ]
        )

    def test_bad_seat_counts_raise(self):
        people = [make("Quill", "Anna")]
        for count in (0, -1):
            with self.assertRaises(ProjectError):
                seat_rows(people, count)

    def test_no_students_raises(self):
        with self.assertRaises(ProjectError):
            seat_rows([], 3)


if __name__ == "__main__":
    unittest.main()
